// Rebuild the application catalog from the reviewed, pinned local SVG subset.
// This tool never downloads assets. --check verifies without writing any files.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { JSDOM } from 'jsdom';

const directory = new URL('./', import.meta.url);
const output = new URL('../../src/shared/tabler-paths.ts', directory);
const manifest = JSON.parse(readFileSync(new URL('provenance.json', directory), 'utf8'));
const sources = new Map();
for (const file of manifest.files) {
  if (!/^(?:[a-z0-9-]+\.svg|LICENSE)$/.test(file.file)) throw new Error('Unexpected source filename.');
  const bytes = readFileSync(new URL(file.file, directory));
  if (createHash('sha256').update(bytes).digest('hex') !== file.sha256) throw new Error(`Source hash changed: ${file.file}`);
  sources.set(file.file, bytes.toString('utf8'));
}
const paths = {};
for (const name of [...new Set(Object.values(manifest.glyphs))].sort()) {
  const svg = new JSDOM(sources.get(name + '.svg'), { contentType: 'image/svg+xml' }).window.document.documentElement;
  if (svg.localName !== 'svg' || svg.getAttribute('viewBox') !== '0 0 24 24') throw new Error(`Unsupported SVG root: ${name}`);
  const expected = { fill: 'none', stroke: 'currentColor', 'stroke-width': '2', 'stroke-linecap': 'round', 'stroke-linejoin': 'round' };
  for (const [key, value] of Object.entries(expected)) if (svg.getAttribute(key) !== value) throw new Error(`Unexpected ${key}: ${name}`);
  const parts = [...svg.children].map(path => {
    if (path.localName !== 'path' || path.attributes.length !== 1 || !path.hasAttribute('d')) throw new Error(`Unsupported SVG node: ${name}`);
    const value = path.getAttribute('d');
    if (!/^M[\d\s.,+eE\-MLHVCSQTAZmlhvcsqtaz]+$/.test(value)) throw new Error(`Unexpected path: ${name}`);
    return value;
  });
  if (!parts.length) throw new Error(`Empty icon: ${name}`);
  paths[name] = parts.join(' ');
}
const license = sources.get('LICENSE').trim().split('\n').map(line => ` * ${line}`.trimEnd()).join('\n');
const source = `/*!
 * Tabler Icons v${manifest.version} — https://github.com/tabler/tabler-icons
${license}
 */
/**
 * PURPOSE    Supply the pinned Tabler interface glyph data.
 * KIND       CORE
 * CONTRACT   IN: none. OUT: frozen app-name-to-path catalog, 24-unit viewBox.
 *            RAISES: none. Data contains reviewed path commands only.
 * GUARANTEES Local immutable strings; no DOM, external URLs or runtime parsing.
 * TUNING     Glyph mapping lives in vendor/tabler/provenance.json.
 * DECISIONS  D1: Join upstream path elements with identical stroke attributes.
 *            Alternative: runtime SVG parsing; rejected to avoid markup authority.
 *            Revisit if a future icon needs a primitive or per-path styling.
 * LIMITS     Generated file; edit the pinned sources/map, then run the generator.
 * TESTBENCH  src/shared/icons.vendor.test.ts — node --import tsx --test src/shared/icons.vendor.test.ts
 * DEMO       src/shared/icons.demo.ts through dev/fixtures/icons.html.
 */
// Generated by node vendor/tabler/generate.mjs; do not edit by hand.
const paths = Object.freeze({
${Object.entries(paths).map(([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`).join('\n')}
});
export const tablerPaths: Readonly<Record<string, string>> = Object.freeze({
${Object.entries(manifest.glyphs).map(([key, value]) => `  ${JSON.stringify(key)}: paths[${JSON.stringify(value)}],`).join('\n')}
});
`;
if (process.argv.includes('--check')) {
  if (readFileSync(output, 'utf8') !== source) throw new Error('Generated Tabler data is stale; run node vendor/tabler/generate.mjs.');
  console.log(`Tabler ${manifest.version}: ${Object.keys(paths).length} source hashes and ${Object.keys(manifest.glyphs).length} catalog mappings verified.`);
} else {
  writeFileSync(output, source);
  console.log(`Generated ${fileURLToPath(output)}.`);
}
